    sources:[{href:"../settingBible%20-%20AltWWII.md",label:"Setting Bible — Micronesia"},{href:"../coProsperitySphereReference%20-%20AltWWII.md",label:"Co-Prosperity Sphere Reference — Pacific territories"},{href:"../transcript.md",label:"Transcript — Micronesian Administration"}],
    categories:["Micronesia","South Seas General Government","Palau","Caroline Islands","Mariana Islands","Marshall Islands"],
    facts:[["Headquarters","Koror"],["Major naval centers","Truk and Saipan"],["Predecessor","South Seas Mandate"],["Excluded enclave","United States territory of Guam"],["Legal status","Direct Japanese imperial territory"],["Nationality","Japanese"]]
